QString FeedPageHsx::name(int id)const{const auto it=session_.data().users().find(id);return it==session_.data().users().end()?QString("用户"):AppSessionHsx::q(it->second->name());}
FeedPageHsx::FeedPageHsx(AppSessionHsx& s,QWidget* parent,const QString& channel):QWidget(parent),session_(s),channel_(channel){
    const bool blog=channel=="weibo";setObjectName(blog?"weiboPage":"momentsPage");auto* layout=new QVBoxLayout(this);layout->setContentsMargins(0,0,0,0);
    tabs_=new QTabWidget;tabs_->setObjectName("socialTabs");layout->addWidget(tabs_);auto* timeline=new QWidget;auto* columns=new QHBoxLayout(timeline);columns->setContentsMargins(0,12,0,0);columns->setSpacing(16);
    auto* center=new QWidget;auto* form=new QVBoxLayout(center);form->setContentsMargins(0,0,0,0);form->setSpacing(14);if(blog){setStyleSheet(weiboContentStyle());form->addWidget(new WeiboHeroHsx);}
    auto* toolbar=new QHBoxLayout;filter_=new QComboBox;filter_->setObjectName("feedFilter");filter_->addItems(blog?QStringList{"推荐 · 全部","我的关注","我的微博"}:QStringList{"好友动态","我的朋友圈"});toolbar->addWidget(filter_);
    search_=new QLineEdit;search_->setObjectName("feedSearch");search_->setPlaceholderText(blog?"搜索微博、作者或 #话题#":"搜索好友动态");toolbar->addWidget(search_,1);form->addLayout(toolbar);
    auto* card=new QFrame;card->setObjectName("card");auto* compose=new QVBoxLayout(card);compose->setContentsMargins(18,16,18,16);auto* title=new QLabel(blog?"有什么新鲜事，想分享给大家？":"记录这一刻，与朋友分享");title->setObjectName("sectionTitle");compose->addWidget(title);
    composer_=new QPlainTextEdit;composer_->setObjectName("feedComposer");composer_->setPlaceholderText(blog?"公开发布 · 无需加好友也能看见，支持 #话题#":"仅你和好友可见 · 文字或图片");composer_->setMaximumHeight(85);compose->addWidget(composer_);photo_=new QLabel;photo_->hide();compose->addWidget(photo_);
    auto* actions=new QHBoxLayout;auto* add=new QPushButton("＋ 图片");add->setObjectName("attachPostImage");actions->addWidget(add);connect(add,&QPushButton::clicked,this,[this]{auto f=QFileDialog::getOpenFileName(this,"选择动态图片",{},"图片 (*.jpg *.jpeg *.png *.bmp)");if(!f.isEmpty())selectImage(f);});
    auto* remove=new QPushButton("移除图片");actions->addWidget(remove);connect(remove,&QPushButton::clicked,this,[this]{image_.clear();photo_->hide();});hint_=new QLabel(blog?"公开动态 · 最近 20 条":"仅好友可见 · 最近 20 条");hint_->setObjectName("muted");actions->addWidget(hint_,1);
    auto* reload=new QPushButton("刷新");reload->setObjectName("refreshFeed");actions->addWidget(reload);connect(reload,&QPushButton::clicked,this,[this]{session_.command("sync",{});});auto* publish=new QPushButton(blog?"发布微博":"发布动态");publish->setObjectName("publishPost");publish->setProperty("primary",true);actions->addWidget(publish);
    connect(publish,&QPushButton::clicked,this,[this]{auto text=composer_->toPlainText().trimmed();if((text.isEmpty()&&image_.isEmpty())||text.toUtf8().size()>2000){hint_->setText("请填写内容或选图，文字最多 2000 字节。");return;}if(session_.command("feed.publish",{{"channel",channel_},{"text",text},{"image",image_}},{},"动态已发布")){composer_->clear();image_.clear();photo_->hide();hint_->setText(channel_=="weibo"?"公开动态 · 最近 20 条":"仅好友可见 · 最近 20 条");}});
    for(auto* b:{add,remove,reload,publish})b->setEnabled(s.remote());compose->addLayout(actions);form->addWidget(card);
    scroll_=new QScrollArea;scroll_->setWidgetResizable(true);scroll_->setFrameShape(QFrame::NoFrame);scroll_->setStyleSheet("QScrollArea {background:transparent;} QScrollArea > QWidget > QWidget {background:transparent;}");auto* content=new QWidget;posts_=new QVBoxLayout(content);posts_->setContentsMargins(0,0,4,0);posts_->setSpacing(12);scroll_->setWidget(content);form->addWidget(scroll_,1);columns->addWidget(center,1);
    if(blog){auto* side=new QFrame;side->setObjectName("card");side->setFixedWidth(210);auto* right=new QVBoxLayout(side);right->setContentsMargins(18,20,18,20);auto* mark=new QLabel("频率收集站 ✦");mark->setStyleSheet("font-size:21px;font-weight:700;color:#925783;");right->addWidget(mark);right->addWidget(new QLabel("YVONNE THEME\n灵感实验室 / 正在营业"));auto* hot=new QLabel("正在讨论");hot->setObjectName("sectionTitle");right->addWidget(hot);trends_=new QLabel;trends_->setTextFormat(Qt::PlainText);trends_->setWordWrap(true);right->addWidget(trends_);right->addStretch();auto* tip=new QLabel("话题来自当前公开动态\n关注与私信不需要加好友\n\n粉色信号，连向你的日常。");tip->setWordWrap(true);tip->setObjectName("muted");right->addWidget(tip);columns->addWidget(side);}
    tabs_->addTab(timeline,blog?"微博首页":"朋友圈");
    if(blog){auto* dm=new QWidget;auto* row=new QHBoxLayout(dm);contacts_=new QListWidget;contacts_->setObjectName("weiboContacts");contacts_->setFixedWidth(200);row->addWidget(contacts_);auto* body=new QVBoxLayout;dmTitle_=new QLabel("选择会话，或从公开微博点击「私信」");dmTitle_->setObjectName("sectionTitle");dmTitle_->setTextFormat(Qt::PlainText);body->addWidget(dmTitle_);history_=new QPlainTextEdit;history_->setObjectName("weiboMessageHistory");history_->setReadOnly(true);body->addWidget(history_,1);auto* bottom=new QHBoxLayout;dmInput_=new QLineEdit;dmInput_->setObjectName("weiboMessageInput");dmInput_->setPlaceholderText("发送私信，无需添加好友");bottom->addWidget(dmInput_,1);auto* send=new QPushButton("发送");send->setObjectName("sendWeiboMessage");bottom->addWidget(send);auto* block=new QPushButton("屏蔽 / 解除");bottom->addWidget(block);body->addLayout(bottom);row->addLayout(body,1);tabs_->addTab(dm,"私信");
        auto sendMessage=[this]{if(dmTarget_&&session_.command("weibo.dm.send",{{"target",dmTarget_},{"post",originPost_},{"text",dmInput_->text()}},{},"私信已保存到对方信箱"))dmInput_->clear();};connect(send,&QPushButton::clicked,this,sendMessage);connect(dmInput_,&QLineEdit::returnPressed,this,sendMessage);
        connect(block,&QPushButton::clicked,this,[this]{if(dmTarget_)session_.command("weibo.block",{{"target",dmTarget_},{"enabled",!session_.social()["socialBlocks"].toArray().contains(dmTarget_)}});});connect(contacts_,&QListWidget::currentItemChanged,this,[this](QListWidgetItem* i){if(i){dmTarget_=i->data(Qt::UserRole).toInt();originPost_.clear();refreshMessages();}});connect(tabs_,&QTabWidget::currentChanged,this,[this](int){refreshMessages();});}
    connect(filter_,&QComboBox::currentIndexChanged,this,[this]{refresh();});connect(search_,&QLineEdit::textChanged,this,[this]{refresh();});
    connect(&s,&AppSessionHsx::operationRejected,this,[this](const QJsonObject& a){if(a["op"]=="weibo.dm.send"&&dmInput_&&a["target"].toInt()==dmTarget_&&dmInput_->text().isEmpty())dmInput_->setText(a["text"].toString());if(a["op"]=="feed.publish"&&a.value("channel").toString("moments")==channel_&&composer_->toPlainText().isEmpty()){composer_->setPlainText(a["text"].toString());image_=a["image"].toString();if(!image_.isEmpty()){QPixmap p;p.loadFromData(QByteArray::fromBase64(image_.toLatin1()));photo_->setPixmap(p.scaled(120,80,Qt::KeepAspectRatio));photo_->show();}}});
}
bool FeedPageHsx::selectImage(const QString& path){try{QImageReader reader(path);reader.setAutoTransform(true);auto size=reader.size();require(size.isValid()&&qint64(size.width())*size.height()<=40000000,"请选择 4000 万像素以内的图片");reader.setScaledSize(size.scaled(640,640,Qt::KeepAspectRatio));auto img=reader.read();require(!img.isNull(),"无法读取图片");QByteArray bytes;for(int quality=80;quality>=20;quality-=15){bytes.clear();QBuffer b(&bytes);b.open(QIODevice::WriteOnly);img.save(&b,"JPEG",quality);if(bytes.size()<=30000)break;}if(bytes.size()>30000){img=img.scaled(320,320,Qt::KeepAspectRatio,Qt::SmoothTransformation);bytes.clear();QBuffer b(&bytes);b.open(QIODevice::WriteOnly);img.save(&b,"JPEG",40);}require(bytes.size()<=30000,"图片过于复杂，请选择较小图片");image_=QString::fromLatin1(bytes.toBase64());photo_->setPixmap(QPixmap::fromImage(img).scaled(120,80,Qt::KeepAspectRatio,Qt::SmoothTransformation));photo_->show();hint_->setText("已选 1 张图片 · 自动压缩后上传");return true;}catch(const std::exception& e){QMessageBox::warning(this,"图片未添加",AppSessionHsx::q(e.what()));return false;}}
void FeedPageHsx::showInbox(){if(channel_=="weibo"){tabs_->setCurrentIndex(1);refreshMessages();}}
void FeedPageHsx::showFollowing(){tabs_->setCurrentIndex(0);filter_->setCurrentIndex(1);}
void FeedPageHsx::showHome(){tabs_->setCurrentIndex(0);filter_->setCurrentIndex(0);}
void FeedPageHsx::openMessage(int target,const QString& post){dmTarget_=target;originPost_=post;tabs_->setCurrentIndex(1);refreshMessages();dmInput_->setFocus();}
void FeedPageHsx::refreshMessages(){if(!contacts_)return;auto messages=session_.social()["directMessages"].toArray();QSet<int> peers;int unread=0;for(auto v:messages){auto m=v.toObject();peers.insert(m["sender"].toInt()==session_.user()?m["recipient"].toInt():m["sender"].toInt());if(m["recipient"].toInt()==session_.user()&&!m["read"].toBool())++unread;}if(dmTarget_)peers.insert(dmTarget_);QSignalBlocker guard(contacts_);contacts_->clear();for(int id:peers){auto* item=new QListWidgetItem(name(id)+(session_.social()["socialBlocks"].toArray().contains(id)?" · 已屏蔽":""),contacts_);item->setData(Qt::UserRole,id);if(id==dmTarget_)contacts_->setCurrentItem(item);}tabs_->setTabText(1,unread?QString("私信 · %1 未读").arg(unread):"私信");if(!dmTarget_)return;dmTitle_->setText("与 "+name(dmTarget_)+" 的微博私信");QStringList lines;bool mark=false;for(auto it=messages.constEnd();it!=messages.constBegin();){auto m=(--it)->toObject();if(m["sender"].toInt()!=dmTarget_&&m["recipient"].toInt()!=dmTarget_)continue;lines<<name(m["sender"].toInt())+"  "+QDateTime::fromSecsSinceEpoch(m["created"].toVariant().toLongLong()).toString("MM-dd HH:mm")+"\n"+m["text"].toString()+"\n";if(m["recipient"].toInt()==session_.user()&&!m["read"].toBool())mark=true;}auto text=lines.join("\n");if(history_->toPlainText()!=text){history_->setPlainText(text);history_->verticalScrollBar()->setValue(history_->verticalScrollBar()->maximum());}if(mark&&tabs_->currentIndex()==1&&isVisible())session_.command("weibo.dm.read",{{"target",dmTarget_}});}
void FeedPageHsx::refresh(){int position=scroll_->verticalScrollBar()->value();while(auto* item=posts_->takeAt(0)){delete item->widget();delete item;}if(channel_=="weibo"&&(!session_.signedIn()||!session_.data().user(session_.user()).services().count(ServiceHsx::Weibo))){auto* label=new QLabel("请先在「账号 → 开通服务」注册微博，再从左下角切换进入。");label->setWordWrap(true);posts_->addWidget(label);posts_->addStretch();return;}if(!session_.remote()){auto* label=new QLabel("当前为离线课程演示。\n请先运行「启动中心服务器.cmd」，再运行「启动图形界面.cmd」并登录。");label->setWordWrap(true);posts_->addWidget(label);posts_->addStretch();composer_->setEnabled(false);hint_->setText("离线演示 · 发布与刷新不可用");return;}
    auto values=channel_=="weibo"?session_.social()["weibo"].toArray():session_.feed();auto following=session_.social()["follows"].toArray();QMap<QString,int> topics;int shown=0;
    for(auto v:values){auto post=v.toObject();auto text=post["text"].toString(),id=post["id"].toString();int author=post["author"].toInt();auto matches=QRegularExpression("#([^#\\n]{1,30})#").globalMatch(text);while(matches.hasNext())++topics[matches.next().captured(1)];if(!search_->text().isEmpty()&&!(text+name(author)).contains(search_->text(),Qt::CaseInsensitive))continue;if(channel_=="weibo"&&filter_->currentIndex()==1&&!following.contains(author))continue;if(((channel_=="weibo"&&filter_->currentIndex()==2)||(channel_=="moments"&&filter_->currentIndex()==1))&&author!=session_.user())continue;
        ++shown;auto* card=new QFrame;card->setObjectName("card");auto* body=new QVBoxLayout(card);body->setContentsMargins(18,16,18,16);body->setSpacing(12);auto* top=new QHBoxLayout;top->addWidget(new AvatarHsx(session_.studio(),author,name(author),40));auto* who=new QLabel(name(author));who->setTextFormat(Qt::PlainText);who->setObjectName("sectionTitle");top->addWidget(who);top->addStretch();auto* time=new QLabel(QDateTime::fromSecsSinceEpoch(post["created"].toVariant().toLongLong()).toString("MM-dd HH:mm"));time->setObjectName("muted");top->addWidget(time);if(channel_=="weibo"&&author!=session_.user()){auto* follow=new QPushButton(following.contains(author)?"已关注":"＋ 关注");follow->setObjectName("followAuthor");follow->setProperty("author",author);top->addWidget(follow);connect(follow,&QPushButton::clicked,this,[this,author,following]{session_.command("weibo.follow",{{"target",author},{"enabled",!following.contains(author)}});});}body->addLayout(top);
        auto* content=new QLabel(text);content->setObjectName("postText");content->setTextFormat(Qt::PlainText);content->setWordWrap(true);content->setTextInteractionFlags(Qt::TextSelectableByMouse);content->setStyleSheet("font-size:15px;padding:8px 0;");body->addWidget(content);
        if(!post["image"].toString().isEmpty()){QPixmap pic;pic.loadFromData(QByteArray::fromBase64(post["image"].toString().toLatin1()));if(!pic.isNull()){auto* button=new QPushButton;button->setObjectName("postImage");button->setIcon(QIcon(pic));auto size=pic.size().scaled(360,240,Qt::KeepAspectRatio);button->setIconSize(size);button->setFixedSize(size+QSize(8,8));body->addWidget(button);connect(button,&QPushButton::clicked,this,[this,pic]{QDialog dialog(this);dialog.setWindowTitle("动态图片");auto* l=new QVBoxLayout(&dialog);auto* image=new QLabel;image->setPixmap(pic);l->addWidget(image);dialog.exec();});}}
        auto* actions=new QHBoxLayout;auto* like=new QPushButton(QString("%1 · %2").arg(post["liked"].toBool()?"已点赞":"赞").arg(post["likes"].toInt()));like->setObjectName("likePost");like->setProperty("postId",id);actions->addWidget(like);connect(like,&QPushButton::clicked,this,[this,id,post]{session_.command("feed.like",{{"post",id},{"enabled",!post["liked"].toBool()}});});auto* comment=new QPushButton("评论");comment->setObjectName("commentPost");actions->addWidget(comment);connect(comment,&QPushButton::clicked,this,[this,id]{bool ok;auto text=QInputDialog::getText(this,"评论","写下你的回应",QLineEdit::Normal,{},&ok);if(ok&&!text.trimmed().isEmpty())session_.command("feed.comment",{{"post",id},{"text",text}});});if(channel_=="weibo"&&author!=session_.user()){auto* dm=new QPushButton("私信");dm->setObjectName("messageAuthor");dm->setProperty("author",author);actions->addWidget(dm);connect(dm,&QPushButton::clicked,this,[this,author,id]{openMessage(author,id);});}actions->addStretch();if(author==session_.user()){auto* remove=new QPushButton("删除");remove->setObjectName("deletePost");actions->addWidget(remove);connect(remove,&QPushButton::clicked,this,[this,id]{if(QMessageBox::question(this,"删除动态","确定删除此动态及其评论？")==QMessageBox::Yes)session_.command("feed.delete",{{"post",id}});});}body->addLayout(actions);for(auto c:post["comments"].toArray()){auto m=c.toObject();auto* line=new QLabel(name(m["author"].toInt())+"："+m["text"].toString());line->setTextFormat(Qt::PlainText);line->setWordWrap(true);line->setStyleSheet("background:#f1f6fc;border-radius:8px;padding:9px;");body->addWidget(line);}posts_->addWidget(card);
    }if(!shown){auto* empty=new QLabel("这里还很安静，分享第一条动态吧。");empty->setObjectName("emptyState");posts_->addWidget(empty);}posts_->addStretch();if(trends_){QStringList hot;for(auto it=topics.begin();it!=topics.end();++it)hot<<QString("#%1#  ·  %2 条").arg(it.key()).arg(it.value());trends_->setText(hot.isEmpty()?"还没有话题，试试发布 #今天的生活#":hot.mid(0,8).join("\n\n"));refreshMessages();}QTimer::singleShot(0,this,[this,position]{scroll_->verticalScrollBar()->setValue(position);});
}
